import{_ as e,r as s,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"|resize - October CMS - 3.x","titleTemplate":false,"description":"Twig 过滤器","frontmatter":{"subtitle":"Twig 过滤器"},"headers":[{"level":2,"title":"自定义文件名","slug":"自定义文件名","link":"#自定义文件名","children":[]},{"level":2,"title":"自定义文件夹名称","slug":"自定义文件夹名称","link":"#自定义文件夹名称","children":[]},{"level":2,"title":"可用来源","slug":"可用来源","link":"#可用来源","children":[]},{"level":2,"title":"PHP 接口","slug":"php-接口","link":"#php-接口","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/markup/filter/resize.md","filePath":"3.x/zh-cn/markup/filter/resize.md"}'),i={name:"3.x/zh-cn/markup/filter/resize.md"};function r(k,n,g,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"|resize",-1)),a(p),n[1]||(n[1]=u(`<p><code>|resize</code> 过滤器尝试使用提供的调整大小配置来调整所提供图像源的大小，并输出调整后图像的 URL。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>该过滤器接受三个参数：<code>|resize(width, height, options)</code>。</p><p>如果过滤器能够调整所提供图像的大小，则返回指向图像调整器的 URL（例如：<code>/resize/filename.png</code>）。对于后续请求，将直接返回调整后图像的 URL。如果过滤器无法处理所提供的图像，则会返回原始 URL，不做任何修改。</p><p>以下代码将把 banner.jpg 媒体图像调整为 1920 x 1080 的比例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media<span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">1920</span><span class="token punctuation">,</span> <span class="token number">1080</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>您还可以传递第三个选项参数。以下示例将裁剪图像。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>crop<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>有关可用的 <code>options</code> 参数的更多信息，请参阅<a href="./../../extend/services/resizer.html">图像调整器文章</a>。</p><h2 id="自定义文件名"><a href="#自定义文件名" class="header-anchor">#</a> 自定义文件名</h2><p>调整器默认会为调整后的图像分配一个随机文件名。您可以通过将 <code>filename</code> 选项设置为 <code>true</code> 来使用原始文件名。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p><code>filename</code> 选项还支持以字符串形式指定自定义文件名。文件名不应包含扩展名，因为将使用原始扩展名。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>您可以使用 <code>extension</code> 选项修改扩展名。此过程将尝试从一种文件类型转换为另一种，例如将 JPG 转换为 PNG 文件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>png<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h2 id="自定义文件夹名称"><a href="#自定义文件夹名称" class="header-anchor">#</a> 自定义文件夹名称</h2><p>使用自定义文件名时，文件名仍会包含一个尾部哈希值以确保在调整器资源目录中的唯一性。在大多数情况下，这足以满足基本的 SEO 需求。例如，文件在系统中将如下所示。</p><ul><li><code>.../800_600_0_0_auto/my-seo-friendly-name_001a14981ffe90700046616c5f415467.png</code></li></ul><p>可以指定 <code>group</code> 作为文件夹名称，这将把图像放置在专用的资源组中。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    group<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>2024-banners<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>例如，上面的代码将把文件放置在以下目录中：</p><ul><li><code>.../800_600_0_0_auto/2024-banners/my-seo-friendly-name.png</code></li></ul><p>但是请注意，这种方法可能容易出现命名冲突。如果使用相同的名称和调整选项调整不同的文件大小，它将输出原始文件，因为路径中没有添加唯一的哈希值。</p><h2 id="可用来源"><a href="#可用来源" class="header-anchor">#</a> 可用来源</h2><p>您可以从多个来源引用图像，包括以下路径：</p><ul><li><code>/app</code></li><li><code>/plugins</code></li><li><code>/themes</code></li><li><code>/modules</code></li><li><code>/storage/app/uploads</code></li><li><code>/storage/app/media</code></li></ul><p>例如：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>/plugins/acme/blog/assets/images/someimage.png<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="php-接口"><a href="#php-接口" class="header-anchor">#</a> PHP 接口</h2><p>您可以在 PHP 中使用 <code>System\\Classes\\ResizeImages</code> 和 <code>resize</code> 方法来调整图像大小。返回值是调整后图像的 URL 位置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>该方法接受宽度（第二个参数）、高度（第三个参数）和<a href="./../../extend/services/resizer.html">调整器选项</a>（第四个参数）。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">,</span> <span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/resizer.html">调整器服务</a></li></ul></div>`,36))])}const w=e(i,[["render",r]]);export{f as __pageData,w as default};
